      return NewGpuMemoryBufferHandle(
          mojo::Clone(*data_.gpu_memory_buffer_handle));
    case Tag::kReadOnlyShmemRegion:
      return NewReadOnlyShmemRegion(
          mojo::Clone(*data_.read_only_shmem_region));
